commits.patch:
diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -271,6 +271,7 @@
       /* in the case of the PFB format, the private dictionary can be */
       /* made of several adjacent segments.                           */
       FT_UShort  tag;
+      FT_UShort  seg_len;
       FT_Byte*   priv_dict = NULL;
       FT_ULong   priv_len  = 0;

@@ -284,11 +285,13 @@
         if ( tag != 0x8002U )
           break;

-        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) ||
-             FT_STREAM_READ( priv_dict + priv_len, size )        )
+        seg_len = (FT_UShort)size;
+
+        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + seg_len ) ||
+             FT_STREAM_READ( priv_dict + priv_len, seg_len )        )
           goto Fail;

-        priv_len += size;
+        priv_len += seg_len;
       }

diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -271,6 +271,7 @@
       /* in the case of the PFB format, the private dictionary can be */
       /* made of several adjacent segments.                           */
       FT_UShort  tag;
+      FT_UShort  seg_len;
       FT_Byte*   priv_dict = NULL;
       FT_ULong   priv_len  = 0;

@@ -284,11 +285,13 @@
         if ( tag != 0x8002U || size > stream->size - stream->pos )
           break;

-        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) ||
-             FT_STREAM_READ( priv_dict + priv_len, size )        )
+        seg_len = (FT_UShort)size;
+
+        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + seg_len ) ||
+             FT_STREAM_READ( priv_dict + priv_len, size )           )
           break;

-        priv_len += size;
+        priv_len += seg_len;
       }
